package oci

import (
	"archive/tar"
	"compress/gzip"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"path"
	"strings"
)

// Client handles OCI registry operations
type Client struct {
	registryURL string
	username    string
	REDACTED    string
	httpClient  *http.Client

	// Limits bounds a template download; the zero value is unbounded.
	Limits Limits
}

// Template represents an OCI template with its files
type Template struct {
	Name    string
	Tag     string
	Entries []ArchiveFile
}

// ArchiveFile is one regular file read from an archive.
type ArchiveFile struct {
	Path       string // relative to the archive root, forward slashes
	Content    []byte
	Executable bool
}

// NewClient creates a new OCI client
func NewClient(registryURL, username, REDACTED string) *Client {
	return &Client{
		registryURL: strings.TrimSuffix(registryURL, "/"),
		username:    username,
		REDACTED:    REDACTED,
		httpClient:  &http.Client{},
	}
}

// ListTags lists available tags for a repository (templates)
func (c *Client) ListTags(repository string) ([]string, error) {
	url := fmt.Sprintf("%s/v2/%s/tags/list", c.registryURL, repository)

	req, err := http.NewRequest("GET", url, nil)
	if err != nil {
		return nil, err
	}

	if c.username != "" && c.REDACTED != "" {
		req.SetBasicAuth(c.username, c.REDACTED)
	}

	resp, err := c.httpClient.Do(req)
	if err != nil {
		return nil, err
	}
	defer func() { _ = resp.Body.Close() }()

	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("failed to list tags: %s (GET %s)", resp.Status, url)
	}

	var result struct {
		Tags []string `json:"tags"`
	}

	if err := json.NewDecoder(resp.Body).Decode(&result); err != nil {
		return nil, err
	}

	return result.Tags, nil
}

// DownloadTemplate downloads and extracts a template from the registry
func (c *Client) DownloadTemplate(repository, tag string) (*Template, error) {
	// Get manifest
	manifestURL := fmt.Sprintf("%s/v2/%s/manifests/%s", c.registryURL, repository, tag)

	req, err := http.NewRequest("GET", manifestURL, nil)
	if err != nil {
		return nil, err
	}

	req.Header.Set("Accept", "application/vnd.oci.image.manifest.v1+json")
	if c.username != "" && c.REDACTED != "" {
		req.SetBasicAuth(c.username, c.REDACTED)
	}

	resp, err := c.httpClient.Do(req)
	if err != nil {
		return nil, err
	}
	defer func() { _ = resp.Body.Close() }()

	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("failed to get manifest: %s", resp.Status)
	}

	var manifest struct {
		Layers []struct {
			MediaType string `json:"mediaType"`
			Digest    string `json:"digest"`
		} `json:"layers"`
	}

	if err := json.NewDecoder(io.LimitReader(resp.Body, 1<<20)).Decode(&manifest); err != nil {
		return nil, err
	}

	if len(manifest.Layers) == 0 {
		return nil, fmt.Errorf("no layers found in manifest")
	}

	// Download first layer (assumed to be tar.gz of template files)
	layerDigest := manifest.Layers[0].Digest
	entries, err := c.downloadAndExtractLayer(repository, layerDigest)
	if err != nil {
		return nil, err
	}

	return &Template{
		Name:    repository,
		Tag:     tag,
		Entries: entries,
	}, nil
}

// downloadAndExtractLayer downloads a layer and extracts its contents
func (c *Client) downloadAndExtractLayer(repository, digest string) ([]ArchiveFile, error) {
	url := fmt.Sprintf("%s/v2/%s/blobs/%s", c.registryURL, repository, digest)

	req, err := http.NewRequest("GET", url, nil)
	if err != nil {
		return nil, err
	}

	if c.username != "" && c.REDACTED != "" {
		req.SetBasicAuth(c.username, c.REDACTED)
	}

	resp, err := c.httpClient.Do(req)
	if err != nil {
		return nil, err
	}
	defer func() { _ = resp.Body.Close() }()

	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("failed to download layer: %s", resp.Status)
	}

	return ReadTarGzLimited(resp.Body, c.Limits)
}

// Limits bounds what reading an archive may hold in memory. A zero field is no
// limit on that axis.
type Limits struct {
	Files int   // regular files
	Bytes int64 // their content, once decompressed
}

// ErrNotRegularFile is returned for an archive entry that is a link, a device
// or anything else that is not a regular file.
var ErrNotRegularFile = errors.New("archive entry is not a regular file")

// ErrArchiveTooLarge is returned when an archive exceeds its Limits.
var ErrArchiveTooLarge = errors.New("archive is larger than allowed")

// ReadTarGz reads a gzipped tar archive into its regular files.
func ReadTarGz(r io.Reader) ([]ArchiveFile, error) {
	return ReadTarGzLimited(r, Limits{})
}

// ReadTarGzLimited is ReadTarGz that stops, with ErrArchiveTooLarge, as soon as
// the archive passes lim — before the rest of it is decompressed.
func ReadTarGzLimited(r io.Reader, lim Limits) ([]ArchiveFile, error) {
	gzr, err := gzip.NewReader(r)
	if err != nil {
		return nil, err
	}
	defer func() { _ = gzr.Close() }()
	return ReadTarLimited(gzr, lim)
}

// ReadTar reads a tar archive into its regular files.
//
// Directories and pax headers are skipped. Anything else that is not a regular
// file — a symlink, a hard link, a device — is refused rather than read: the
// old behavior turned a symlink into an empty file, which is a template
// silently missing what it says it contains.
func ReadTar(r io.Reader) ([]ArchiveFile, error) {
	return ReadTarLimited(r, Limits{})
}

// ReadTarLimited is ReadTar that refuses, with ErrArchiveTooLarge, an archive
// past lim without reading the rest of it into memory.
func ReadTarLimited(r io.Reader, lim Limits) ([]ArchiveFile, error) {
	tr := tar.NewReader(r)
	var files []ArchiveFile
	var total int64

	for {
		header, err := tr.Next()
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, err
		}

		switch header.Typeflag {
		case tar.TypeDir, tar.TypeXGlobalHeader:
			continue
		case tar.TypeReg:
		default:
			return nil, fmt.Errorf("%w: %q (type %q)", ErrNotRegularFile, header.Name, header.Typeflag)
		}

		if lim.Files > 0 && len(files) >= lim.Files {
			return nil, ErrArchiveTooLarge
		}
		var src io.Reader = tr
		if lim.Bytes > 0 {
			// One byte past what is left is enough to tell "exactly at the
			// limit" from "over it".
			src = io.LimitReader(tr, lim.Bytes-total+1)
		}
		content, err := io.ReadAll(src)
		if err != nil {
			return nil, err
		}
		total += int64(len(content))
		if lim.Bytes > 0 && total > lim.Bytes {
			return nil, ErrArchiveTooLarge
		}

		path, err := sanitizeArchivePath(header.Name)
		if err != nil {
			return nil, err
		}

		files = append(files, ArchiveFile{
			Path:       path,
			Content:    content,
			Executable: header.Mode&0o111 != 0,
		})
	}

	return files, nil
}

// sanitizeArchivePath normalises a tar member name into a path relative to the
// archive root, and rejects anything that escapes it. Returning the parent
// references verbatim would hand a Zip Slip to any caller that writes these
// keys under a target directory.
func sanitizeArchivePath(name string) (string, error) {
	// Tar always uses forward slashes; normalise Windows-style separators so a
	// member named `..\..\etc\passwd` is not waved through as a plain filename.
	clean := strings.ReplaceAll(name, `\`, "/")
	// Drop the leading separator *before* cleaning: path.Clean("/../x") returns
	// "/x", which would silently absorb the traversal instead of exposing it.
	clean = path.Clean(strings.TrimLeft(clean, "/"))

	if clean == "" || clean == "." {
		return "", fmt.Errorf("archive contains an entry with an empty path: %q", name)
	}
	if clean == ".." || strings.HasPrefix(clean, "../") {
		return "", fmt.Errorf("archive entry escapes the root: %q", name)
	}

	return clean, nil
}

package oci

import (
	"errors"
	"fmt"
	"io"
	"math"
	"net/http"
	"net/url"
	"strconv"
)

// MaxRedirects is net/http's default limit, kept now that CheckRedirect is set.
const MaxRedirects = 10

// RefuseOffOriginRedirect keeps credentials on the origin they were meant for.
// It compares with the initial request (via[0]), not only the previous hop, so
// a chain that leaves the origin and comes back is refused too. The redirect is
// refused rather than followed without Authorization: a registry that moves
// content to another host is misconfigured for this client, and an explicit
// error is safer than a silent anonymous retry.
func RefuseOffOriginRedirect(req *http.Request, via []*http.Request) error {
	if len(via) >= MaxRedirects {
		return ErrTooManyRedirects
	}
	if !sameOrigin(via[0].URL.String(), req.URL.String()) {
		return fmt.Errorf("%w (%s)", ErrOffOriginRedirect, req.URL.Host)
	}
	return nil
}

// ErrOffOriginRedirect is the refusal RefuseOffOriginRedirect returns.
var ErrOffOriginRedirect = errors.New("refusing redirect to another origin")

// ErrTooManyRedirects is returned once a request was redirected MaxRedirects
// times. net/http wraps it in a *url.Error carrying the last target URL, so
// callers pass the error through StripRedirectTarget.
var ErrTooManyRedirects = errors.New("stopped after " + strconv.Itoa(MaxRedirects) + " redirects")

// errInsecureRedirect is the refusal of a redirect from https to http, so a
// credential or a signed URL does not leave in clear.
var errInsecureRedirect = errors.New("refusing redirect from https to http")

// StripRedirectTarget strips the target URL from a refused redirect. net/http
// wraps the refusal in a *url.Error carrying the full target URL, which may hold
// a signed query; only the meaning and the host (kept by the refusal itself)
// remain. Other errors pass through unchanged.
func StripRedirectTarget(err error) error {
	var ue *url.Error
	if !errors.As(err, &ue) {
		return err
	}
	for _, sentinel := range []error{ErrOffOriginRedirect, ErrTooManyRedirects, errInsecureRedirect} {
		if errors.Is(ue.Err, sentinel) {
			return ue.Err
		}
	}
	return err
}

// ErrBodyTooLarge is returned by ReadAllLimited when the body is over the limit.
var ErrBodyTooLarge = errors.New("size limit exceeded")

// ReadAllLimited reads r to its end, accepting at most limit bytes (limit >= 0;
// a negative limit is refused with ErrBodyTooLarge without reading). It takes
// limit+1 bytes at most from r: a body over the limit is an ErrBodyTooLarge, not
// a silent cut, and a read error is returned as is, never mistaken for a size.
// With limit = math.MaxInt64 the extra byte cannot be asked for, so the read is
// capped at limit and an overflow cannot be told apart.
func ReadAllLimited(r io.Reader, limit int64) ([]byte, error) {
	if limit < 0 {
		return nil, fmt.Errorf("response body over %d bytes: %w", limit, ErrBodyTooLarge)
	}
	n := limit
	if n < math.MaxInt64 {
		n++
	}
	body, err := io.ReadAll(io.LimitReader(r, n))
	if err != nil {
		return nil, err
	}
	if int64(len(body)) > limit {
		return nil, fmt.Errorf("response body over %d bytes: %w", limit, ErrBodyTooLarge)
	}
	return body, nil
}

// RedactURL returns raw with the password of its userinfo masked, safe to put in
// an error or a log. raw must be an absolute URL: one that does not parse, or
// that has no host (such as "user:pass@host", read as a scheme and an opaque
// part), is not echoed, since it may still hold a password. An empty raw stays
// empty.
func RedactURL(raw string) string {
	if raw == "" {
		return ""
	}
	u, err := url.Parse(raw)
	if err != nil || u.Host == "" {
		return "<invalid URL>"
	}
	return u.Redacted()
}
package oci

import (
	"encoding/base64"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
	"time"
)

// DEVDESK-412 step 3: oci.Client (template tags and manifest) keeps its
// credentials on the origin they were meant for and is bounded in time. Server
// A plays the registry, server B another origin (same host, other port). The
// blob download is deliberately not covered here: it keeps its own policy
// (step 4), and these tests must not pin what happens to a redirected blob.

const (
	clientTestUser = "user"
	clientTestPass = "S3CRETPW"
)

// clientTestDigest is a well-formed layer digest, so the fixtures stay valid if
// the blob is later checked against the manifest.
var clientTestDigest = "sha256:" + strings.Repeat("a", 64)

// clientOp is one public entry point of oci.Client that starts with a request
// the origin guard must cover.
type clientOp struct {
	name string
	run  func(c *Client) error
}

func clientOps() []clientOp {
	return []clientOp{
		{"ListTags", func(c *Client) error {
			_, err := c.ListTags("tpl")
			return err
		}},
		{"DownloadTemplate", func(c *Client) error {
			_, err := c.DownloadTemplate("tpl", "v1")
			return err
		}},
	}
}

// basicHeader is the Authorization value the client must send for the test
// credentials.
func basicHeader() string {
	return "Basic " + base64.StdEncoding.EncodeToString([]byte(clientTestUser+":"+clientTestPass))
}

// authsOf returns the Authorization header of every recorded hit whose
// "host path" contains pathPart, in arrival order.
func authsOf(l *hitLog, pathPart string) []string {
	l.mu.Lock()
	defer l.mu.Unlock()
	var out []string
	for i, h := range l.hits {
		if strings.Contains(h, pathPart) {
			out = append(out, l.auth[i])
		}
	}
	return out
}

func TestClientRefusesOffOriginRedirect(t *testing.T) {
	for _, op := range clientOps() {
		t.Run(op.name, func(t *testing.T) {
			var bHits, aHits hitLog
			b := recordingServer(t, &bHits)
			a := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				aHits.record(r)
				// Every request of the registry, tags or manifest, is sent to
				// the other origin with a signed query.
				http.Redirect(w, r, b.URL+"/x?sig=SECRET", http.StatusTemporaryRedirect)
			}))
			t.Cleanup(a.Close)

			c := NewClient(a.URL, clientTestUser, clientTestPass)
			err := op.run(c)

			if !errors.Is(err, ErrOffOriginRedirect) {
				t.Fatalf("err = %v, want errors.Is ErrOffOriginRedirect", err)
			}
			if n := bHits.count(); n != 0 {
				t.Errorf("the other origin received %d requests, want 0", n)
			}
			if got := bHits.anyAuth(); got != "" {
				t.Errorf("the other origin saw Authorization %q", got)
			}
			if got := authsOf(&aHits, ""); len(got) != 1 || got[0] != basicHeader() {
				t.Errorf("registry Authorization headers = %q, want one Basic header", got)
			}
			for _, leak := range []string{"sig=SECRET", "SECRET", clientTestPass, "/x"} {
				if strings.Contains(err.Error(), leak) {
					t.Errorf("error %q leaks %q", err, leak)
				}
			}
		})
	}
}

// clientTarGz serves as the layer the same-origin test downloads.
func clientTarGz(t *testing.T) []byte {
	t.Helper()
	data, err := io.ReadAll(buildTarGz(t, []tarEntry{{name: "Dockerfile", body: "FROM scratch\n"}}))
	if err != nil {
		t.Fatalf("reading fixture archive: %v", err)
	}
	return data
}

func TestClientFollowsSameOriginRedirect(t *testing.T) {
	archive := clientTarGz(t)

	cases := []struct {
		op       clientOp
		moved    string // a path the registry redirects to, same origin
		fromPart string // path part of the first hop
	}{
		{clientOps()[0], "/v2/tpl/moved-tags", "/tags/list"},
		{clientOps()[1], "/v2/tpl/moved-manifests/v1", "/manifests/"},
	}
	for _, tc := range cases {
		t.Run(tc.op.name, func(t *testing.T) {
			var hits hitLog
			a := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				hits.record(r)
				switch {
				case strings.Contains(r.URL.Path, "/moved-tags"):
					_, _ = fmt.Fprint(w, `{"tags":["v1"]}`)
				case strings.Contains(r.URL.Path, "/moved-manifests/"):
					_, _ = fmt.Fprintf(w, `{"layers":[{"mediaType":"application/vnd.oci.image.layer.v1.tar+gzip","digest":%q}]}`, clientTestDigest)
				case strings.Contains(r.URL.Path, "/blobs/"):
					_, _ = w.Write(archive)
				default:
					http.Redirect(w, r, tc.moved, http.StatusFound)
				}
			}))
			t.Cleanup(a.Close)

			c := NewClient(a.URL, clientTestUser, clientTestPass)
			if err := tc.op.run(c); err != nil {
				t.Fatalf("same-origin redirect refused or failed: %v", err)
			}

			first := authsOf(&hits, tc.fromPart)
			second := authsOf(&hits, "/moved-")
			if len(first) != 1 || len(second) != 1 {
				t.Fatalf("hops: first %d, second %d, want 1 and 1", len(first), len(second))
			}
			if first[0] != basicHeader() {
				t.Errorf("first hop Authorization = %q, want the Basic header", first[0])
			}
			if second[0] != basicHeader() {
				t.Errorf("second hop Authorization = %q, want the Basic header", second[0])
			}
		})
	}
}

func TestNewClientIsBounded(t *testing.T) {
	c := NewClient("http://registry.test", clientTestUser, clientTestPass)

	if templateClientTimeout != time.Minute {
		t.Errorf("templateClientTimeout = %v, want 1 minute (decision Q2)", templateClientTimeout)
	}
	if c.httpClient.Timeout != templateClientTimeout {
		t.Errorf("httpClient.Timeout = %v, want templateClientTimeout (%v)", c.httpClient.Timeout, templateClientTimeout)
	}
	if c.httpClient.CheckRedirect == nil {
		t.Fatal("httpClient.CheckRedirect = nil, want the origin guard")
	}

	// The hook is the guard itself, not just any function: another origin is
	// refused, the same origin is accepted, without any network traffic.
	first, _ := http.NewRequest(http.MethodGet, "http://registry.test/v2/tpl/manifests/v1", nil)
	other, _ := http.NewRequest(http.MethodGet, "http://cdn.test/x", nil)
	same, _ := http.NewRequest(http.MethodGet, "http://registry.test/elsewhere", nil)
	if err := c.httpClient.CheckRedirect(other, []*http.Request{first}); !errors.Is(err, ErrOffOriginRedirect) {
		t.Errorf("CheckRedirect(other origin) = %v, want ErrOffOriginRedirect", err)
	}
	if err := c.httpClient.CheckRedirect(same, []*http.Request{first}); err != nil {
		t.Errorf("CheckRedirect(same origin) = %v, want nil", err)
	}
}
